  function getVal(r,aliases){const m={};Object.keys(r||{}).forEach(k=>m[hdr(k)]=r[k]);for(const a of aliases){const k=hdr(a);if(Object.prototype.hasOwnProperty.call(m,k)&&String(m[k]??'').trim()!=='')return m[k]}return ''}
  function dateISO(v){if(!v)return'';if(v instanceof Date&&!isNaN(v))return v.toISOString().slice(0,10);if(typeof v==='number'&&window.XLSX?.SSF?.parse_date_code){const d=XLSX.SSF.parse_date_code(v);if(d?.y)return `${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`}const s=String(v).trim();let m=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](20\d{2})/);if(m)return `${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`;m=s.match(/^(20\d{2})[\/-](\d{1,2})[\/-](\d{1,2})/);if(m)return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;const d=new Date(s);return Number.isFinite(d.getTime())?d.toISOString().slice(0,10):''}
